<?php
declare(strict_types=1);
require __DIR__.'/harness.php';require __DIR__.'/database.php';require __DIR__.'/support-split-fixture.php';
use Hostider\Core\Id;use Hostider\Core\Http\HttpError;
use Hostider\Support\Advanced\{Common,Csat,Incidents};
function iFixture(bool $sla=false,bool $mail=false):array{$f=hFixture($sla,$mail);$f['advanced']=new Common($f['c']);return $f;}
function iSnapshot(array $f):array{$v=hSnapshot($f);foreach(['job_attempts','dead_letters'] as $table){$rows=$f['db']->execute('SELECT * FROM '.$table.' ORDER BY 1')->fetchAll();$v[$table]=hash('sha256',\Hostider\Core\CanonicalJson::encode($rows));}return $v;}
function iDenied(array $f,Closure $work,?int $status=null):void{$before=iSnapshot($f);$e=raises(HttpError::class,$work);if($status!==null){same($status,$e->status);}same($before,iSnapshot($f));}
function iRace(array $f,array $requests):array{$ps=[];foreach($requests as $p){$pipes=[];$v=proc_open([PHP_BINARY,__DIR__.'/support-integration-child.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,null,bEnvironment($f));if(!is_resource($v)){throw new RuntimeException('F5I_CHILD');}fwrite($pipes[0],json_encode($p,JSON_THROW_ON_ERROR));fclose($pipes[0]);$ps[]=[$v,$pipes];}$out=[];foreach($ps as [$v,$pipes]){$s=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);same(0,proc_close($v));same('',$err);$out[]=json_decode($s,true,32,JSON_THROW_ON_ERROR);}return $out;}
function iRating(array $f,array $t,int $version=0):array{return ['ticket_id'=>$t['id'],'ticket_version'=>(int)bRow($f,$t)['version'],'version'=>$version,'score'=>4,'comment'=>'Synthetic integration rating'];}
function iCsat(array $f):Csat{dCommand($f,'csat-policy',['department_id'=>$f['departments'][0],'version'=>0,'window_seconds'=>3600]);return new Csat(new Common($f['c']));}

test('F5-I 01 split source customer and child staff/customer replies remain independent',function():void{$f=iFixture(true);$a=hSource($f);$b=hSplit($f,$a);bReply($f,$a,client:true);bReply($f,$b);bReply($f,$b,client:true);same(2,count(gDetail($f,$a)['messages']));same(3,count(gDetail($f,$b)['messages']));same(5,(int)$f['db']->execute('SELECT COUNT(*) FROM support_messages')->fetchColumn());same(4,(int)bRow($f,$a)['version']);same(3,(int)bRow($f,$b)['version']);same('WAITING_STAFF',bRow($f,$a)['status']);same('WAITING_STAFF',bRow($f,$b)['status']);});
test('F5-I 02 child SLA and assignment change without source Work mutation',function():void{$f=iFixture(true);bRoster($f,$f['admin']['user']);$a=hSource($f);$b=hSplit($f,$a);$source=hSourceWork($f,$a);same(false,bWork($f,$a)['cycle_id']===bWork($f,$b)['cycle_id']);bCommand($f,'assign',['id'=>$b['id'],'version'=>(int)bRow($f,$b)['version'],'assignee_id'=>$f['admin']['user']]);same($source,hSourceWork($f,$a));same($f['admin']['user'],bWork($f,$b)['assignee_id']);same(null,bWork($f,$a)['assignee_id']);bReply($f,$b);same($source,hSourceWork($f,$a));});
test('F5-I 03 split versus queued auto-close serializes without duplicate child or close',function():void{$f=iFixture(true);fPolicy($f);$a=hSource($f);fResolve($f,$a);fDue();same(1,$f['auto']->run()['queued']);$body=hPrepare($f,$a);$rows=iRace($f,[['op'=>'split','ref'=>$f['admin']['reference'],'body'=>$body,'key'=>Id::uuid()],['op'=>'worker']]);foreach($rows as $x){same(true,in_array($x['status'],[200,409],true));}$splits=(int)$f['db']->execute('SELECT COUNT(*) FROM support_ticket_splits')->fetchColumn();same($rows[0]['status']===200?1:0,$splits);same(true,fClosed($f)<=1);same(false,$splits===1&&fClosed($f)===1);same(2,(int)$f['db']->execute('SELECT COUNT(*) FROM support_messages')->fetchColumn());});
test('F5-I 04 queued merge SOURCE auto-close job cannot mutate frozen source',function():void{$f=iFixture(true);fPolicy($f);$a=fTicket($f);$b=bTicket($f);fDue();same(1,$f['auto']->run()['queued']);gMerge($f,$a,$b);$before=hSourceWork($f,$a);$row=bRow($f,$a);$messages=gHash($f,['support_messages']);same(true,fWorker($f));same($before,hSourceWork($f,$a));same($row,bRow($f,$a));same($messages,gHash($f,['support_messages']));same(0,fClosed($f));same('SUCCEEDED',$f['db']->execute("SELECT status FROM jobs WHERE job_type='support.auto-close'")->fetchColumn());});
test('F5-I 05 merge TARGET keeps independent native SLA and CSAT',function():void{$f=iFixture(true);$csat=iCsat($f);$a=fTicket($f);$b=bTicket($f);$source=hSourceWork($f,$a);gMerge($f,$a,$b);bReply($f,$b);fResolve($f,$b);$rating=$csat->command($f['client']['reference'],iRating($f,$b),Id::uuid(),Id::uuid());same(1,$rating['version']);same($source,hSourceWork($f,$a));same($b['id'],$f['db']->execute('SELECT ticket_id FROM support_ratings')->fetchColumn());iDenied($f,fn()=>$csat->command($f['client']['reference'],iRating($f,$a),Id::uuid(),Id::uuid()),409);});
test('F5-I 06 split selected attachment retention preserves membership and immutable history',function():void{$f=iFixture(mail:true);$a=hSource($f);$file=$f['files']->upload($f['client']['reference'],'client',['ticket_id'=>$a['id'],'message_id'=>$a['message_id'],'version'=>(int)bRow($f,$a)['version'],'name'=>'synthetic.pdf','base64'=>base64_encode(\Hostider\Support\Mail\Attachments::FIXTURE)],Id::uuid(),Id::uuid());$b=hSplit($f,$a);$history=gHash($f,['support_messages','support_ticket_splits','support_split_members','support_split_messages']);$token=$f['files']->token($f['client']['reference'],'client',$file['id']);same(\Hostider\Support\Mail\Attachments::FIXTURE,$f['files']->download($f['client']['reference'],'client',$file['id'],$token['token'],Id::uuid())['bytes']);iDenied($f,fn()=>$f['files']->token($f['other']['reference'],'client',$file['id']),404);$f['db']->execute('UPDATE support_mail_files SET expires_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 DAY) WHERE id=?',[$file['id']]);(new \Hostider\Support\Mail\Retention($f['mail'],$f['files']->store))->run();same($history,gHash($f,['support_messages','support_ticket_splits','support_split_members','support_split_messages']));same(1,(int)$f['db']->execute('SELECT physical_removed FROM support_mail_files WHERE id=?',[$file['id']])->fetchColumn());iDenied($f,fn()=>$f['files']->token($f['client']['reference'],'client',$file['id']),404);same([$a['message_id']],array_column(gDetail($f,$b)['messages'],'id'));});
test('F5-I 07 merge SOURCE CSAT incident and queued outbound guards are atomic',function():void{$f=iFixture(mail:true);$csat=iCsat($f);$a=fTicket($f);$b=bTicket($f);bReply($f,$a);fResolve($f,$a);$incident=dCommand($f,'incident-new',['department_id'=>$f['departments'][0],'version'=>0,'title'=>'Synthetic incident','description'=>'Public','private_root'=>'Private','affected'=>'Synthetic']);$mail=cDelivery($f,$a);gMerge($f,$a,$b);dPublish($f);iDenied($f,fn()=>$csat->command($f['client']['reference'],iRating($f,$a),Id::uuid(),Id::uuid()),409);iDenied($f,fn()=>$f['c']->identity->withStepUp($f['admin']['reference'],'admin',function($u,$s)use($f,$a,$incident){$t=$f['service']->access->ticket($u,$s,$a['id']);return (new Incidents(new Common($f['c'])))->link($u,$s,$t,$incident['id'],Id::uuid());}),409);$p=['event_uuid'=>$mail['event_id'],'support_event_uuid'=>$mail['support_event_id'],'ticket_id'=>$a['id'],'customer_id'=>$f['client']['customer'],'message_id'=>$mail['message_id']];$before=iSnapshot($f);same('FAILED',$f['outbound']->ready($p));same($before,iSnapshot($f));same(0,(int)$f['db']->execute('SELECT COUNT(*) FROM support_mail_transport')->fetchColumn());});
test('F5-I 08 split merge chains and both endpoints reject without business writes',function():void{$f=iFixture();$a=hSource($f);$b=hSplit($f,$a);$c=bTicket($f);foreach([$a,$b] as $t){iDenied($f,fn()=>hPrepare($f,$t,[$a['message_id']]));iDenied($f,fn()=>gPrepare($f,$t,$c));iDenied($f,fn()=>gPrepare($f,$c,$t));}same(1,(int)$f['db']->execute('SELECT COUNT(*) FROM support_ticket_splits')->fetchColumn());same(0,gCount($f));});
test('F5-I 09 stale split confirmation after native reply creates no partial child',function():void{$f=iFixture();$a=hSource($f);$body=hPrepare($f,$a);bReply($f,$a,client:true);iDenied($f,fn()=>hExecute($f,$body),409);same(0,(int)$f['db']->execute('SELECT COUNT(*) FROM support_ticket_splits')->fetchColumn());});
test('F5-I 10 duplicate key replay and different-key confirmation replay are distinct',function():void{$f=iFixture();$a=hSource($f);$body=hPrepare($f,$a);$key=Id::uuid();$x=hExecute($f,$body,$key);$before=iSnapshot($f);same($x,hExecute($f,$body,$key));same($before,iSnapshot($f));iDenied($f,fn()=>hExecute($f,$body),409);$f['db']->execute('UPDATE identity_mfa SET enabled=FALSE WHERE user_id=?',[$f['admin']['user']]);iDenied($f,fn()=>hExecute($f,$body,$key),403);});
test('F5-I 11 current session MFA grant membership revoke preserve all business tables',function():void{foreach(['session','mfa','grant','membership'] as $kind){$f=iFixture();$a=hSource($f);$body=hPrepare($f,$a);if($kind==='session'){$f['db']->transaction(fn()=>$f['c']->identity->invalidate($f['admin']['user']));}elseif($kind==='mfa'){$f['db']->execute('UPDATE identity_mfa SET enabled=FALSE WHERE user_id=?',[$f['admin']['user']]);}elseif($kind==='grant'){$f['db']->execute("DELETE FROM identity_grants WHERE permission='support.ticket.split'");}else{$f['db']->execute('DELETE FROM support_department_members WHERE user_id=?',[$f['admin']['user']]);}iDenied($f,fn()=>hExecute($f,$body));same(1,(int)$f['db']->execute('SELECT COUNT(*) FROM support_tickets')->fetchColumn());}});
test('F5-I 12 source private notes remain isolated from child and foreign customer',function():void{$f=iFixture();$a=hSource($f);$note=bReply($f,$a,'note');$b=hSplit($f,$a);$client=gDetail($f,$b);same(false,str_contains(json_encode($client),$note['message_id']));same(false,str_contains(json_encode($client),$f['admin']['user']));same(1,count($client['messages']));iDenied($f,fn()=>$f['service']->view($f['other']['reference'],'client','detail',['id'=>$b['id']]),404);iDenied($f,fn()=>hPrepare($f,$a,[$note['message_id']]));});
test('F5-I 13 four concurrent workers close split participants independently once',function():void{$f=iFixture(true);fPolicy($f);$a=hSource($f);$b=hSplit($f,$a);fResolve($f,$a);fResolve($f,$b);$messages=gHash($f,['support_messages']);fDue();same(2,$f['auto']->run()['queued']);$rows=iRace($f,array_fill(0,4,['op'=>'worker']));foreach($rows as $x){if($x['status']!==200){echo 'F5I_OBSERVATION '.json_encode($x,JSON_THROW_ON_ERROR).PHP_EOL;}same(200,$x['status']);}usleep(2100000);for($n=0;$n<4;++$n){fWorker($f);}same(2,fClosed($f));same('CLOSED',bRow($f,$a)['status']);same('CLOSED',bRow($f,$b)['status']);same($messages,gHash($f,['support_messages']));same(2,(int)$f['db']->execute("SELECT COUNT(*) FROM jobs WHERE job_type='support.auto-close' AND status='SUCCEEDED'")->fetchColumn());same(0,$f['auto']->run()['queued']);});
test('F5-I 14 native HELD outbox queue audit and immutable split events reconcile',function():void{$f=iFixture(mail:true);$a=hSource($f);$b=hSplit($f,$a);$original=gHash($f,['support_messages','support_ticket_splits','support_split_messages','support_work_events']);cDrain($f);same($original,gHash($f,['support_messages','support_ticket_splits','support_split_messages','support_work_events']));same(0,(int)$f['db']->execute('SELECT COUNT(*) FROM support_mail_transport')->fetchColumn());same(0,(int)$f['db']->execute("SELECT COUNT(*) FROM jobs WHERE status<>'SUCCEEDED'")->fetchColumn());same(0,(int)$f['db']->execute('SELECT COUNT(*) FROM outbox_events WHERE published_at IS NULL')->fetchColumn());same(true,(int)$f['db']->execute('SELECT COUNT(*) FROM audit_logs')->fetchColumn()>0);foreach(['support_ticket_splits','support_split_members','support_split_messages','support_work_events'] as $table){$before=iSnapshot($f);raises(PDOException::class,fn()=>$f['db']->execute('DELETE FROM '.$table));same($before,iSnapshot($f));}});
test('F5-I 15 fault after child SLA creation rolls back all split effects and permits reviewed retry',function():void{$f=iFixture(true);$a=hSource($f);$body=hPrepare($f,$a);$before=iSnapshot($f);$f['db']->execute("CREATE TRIGGER synthetic_integration_split_fault BEFORE INSERT ON support_ticket_splits FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic integration fault'");try{raises(PDOException::class,fn()=>hExecute($f,$body));same($before,iSnapshot($f));}finally{$f['db']->execute('DROP TRIGGER synthetic_integration_split_fault');}hExecute($f,$body);same(1,(int)$f['db']->execute('SELECT COUNT(*) FROM support_ticket_splits')->fetchColumn());});
test('F5-I 16 native HTTP CSRF and client split mutation preserve business state',function():void{$f=iFixture();$a=hSource($f);$b=hSplit($f,$a);$server=new HttpTestServer(dirname(__DIR__),bEnvironment($f),__DIR__.'/commerce-router.php');$admin=['cookies'=>[],'csrf'=>''];$client=['cookies'=>[],'csrf'=>''];try{bLogin($server,$f['admin'],$admin);dClientLogin($server,$f['client'],$client);$before=iSnapshot($f);same(403,bHttp($server,'/api/v1/admin/support-split/prepare',$admin,hBody($f,$a),csrf:false)[0]);same($before,iSnapshot($f));same(404,bHttp($server,'/api/v1/client/support-split/prepare',$client,hBody($f,$a))[0]);same($before,iSnapshot($f));$view=bHttp($server,'/api/v1/client/support-ui/detail?id='.$b['id'],$client);same(200,$view[0]);same([$a['message_id']],array_column($view[1]['data']['messages'],'id'));}finally{$server->stop();}});
test('F5-I 17 native concurrent queue claims must not leak deadlocks or lose lease accounting',function():void{$f=iFixture();$q=new \Hostider\Core\Queue\Queue($f['db']);$f['db']->transaction(function()use($q):void{for($i=0;$i<2;++$i){$q->enqueue('synthetic.claim-only',['case'=>$i],'synthetic-claim-'.$i,Id::uuid(),true);}});$f['db']->execute("CREATE TRIGGER synthetic_claim_overlap BEFORE UPDATE ON jobs FOR EACH ROW BEGIN IF OLD.status='PENDING' AND NEW.status='RUNNING' THEN DO SLEEP(0.15); END IF; END");try{$rows=iRace($f,array_fill(0,4,['op'=>'noop-worker']));foreach($rows as $x){if($x['status']!==200){echo 'F5I_OBSERVATION '.json_encode($x,JSON_THROW_ON_ERROR).PHP_EOL;}same(200,$x['status']);}same(2,(int)$f['db']->execute("SELECT COUNT(*) FROM jobs WHERE status='SUCCEEDED'")->fetchColumn());same(2,(int)$f['db']->execute("SELECT COUNT(*) FROM job_attempts WHERE outcome='SUCCEEDED'")->fetchColumn());same(0,(int)$f['db']->execute("SELECT COUNT(*) FROM jobs WHERE status IN ('RUNNING','UNKNOWN','FAILED')")->fetchColumn());}finally{$f['db']->execute('DROP TRIGGER synthetic_claim_overlap');}});
test('F5-I 18 claim retry never repeats an unsafe external handler',function():void{$f=iFixture();$q=new \Hostider\Core\Queue\Queue($f['db']);$f['db']->transaction(fn()=>$q->enqueue('synthetic.unsafe',[],'synthetic-unsafe',Id::uuid(),false));$calls=0;$w=new \Hostider\Core\Queue\Worker($f['db'],$q);$w->register('synthetic.unsafe',function()use(&$calls):never{++$calls;$e=new PDOException('Synthetic handler failure');$e->errorInfo=['40001',1213,'Synthetic handler failure'];throw $e;});same(true,$w->once());same(1,$calls);same('UNKNOWN',$f['db']->execute('SELECT status FROM jobs')->fetchColumn());same(1,(int)$f['db']->execute('SELECT attempts FROM jobs')->fetchColumn());same(false,$w->once());same(1,$calls);});
test('F5-I 19 exhausted claim deadlock retry remains bounded and rolls back all business effects',function():void{$f=iFixture();$q=new \Hostider\Core\Queue\Queue($f['db']);$f['db']->transaction(fn()=>$q->enqueue('synthetic.claim-only',[],'synthetic-exhaustion',Id::uuid(),true));$before=iSnapshot($f);$f['db']->execute('SET @synthetic_claim_calls=0');$f['db']->execute("CREATE TRIGGER synthetic_claim_exhaustion BEFORE UPDATE ON jobs FOR EACH ROW BEGIN SET @synthetic_claim_calls=@synthetic_claim_calls+1; SIGNAL SQLSTATE '40001' SET MYSQL_ERRNO=1213,MESSAGE_TEXT='Synthetic retry exhaustion'; END");try{raises(PDOException::class,fn()=>$q->claim());same(5,(int)$f['db']->execute('SELECT @synthetic_claim_calls')->fetchColumn());same($before,iSnapshot($f));same(0,(int)$f['db']->execute('SELECT COUNT(*) FROM job_attempts')->fetchColumn());}finally{$f['db']->execute('DROP TRIGGER synthetic_claim_exhaustion');}});
exit(executeTests());
